  test('TFFU-032: orphan page approximation: each scanned page is linked from another scanned page', async () => {
        const pages = [{"path":"/","url":"http://127.0.0.1:56307/","inboundCandidates":["http://127.0.0.1:56307/","http://127.0.0.1:56307/login","http://127.0.0.1:56307/notes","http://127.0.0.1:56307/notes"]},{"path":"/login","url":"http://127.0.0.1:56307/login","inboundCandidates":["http://127.0.0.1:56307/","http://127.0.0.1:56307/login","http://127.0.0.1:56307/notes"]},{"path":"/notes","url":"http://127.0.0.1:56307/notes","inboundCandidates":["http://127.0.0.1:56307/","http://127.0.0.1:56307/login","http://127.0.0.1:56307/notes"]}];
        const inboundMap = new Map();

        for (const page of pages) {
            inboundMap.set(page.url.replace(/#.*$/, ''), 0);
        }

        for (const page of pages) {
            for (const linkedUrl of page.inboundCandidates) {
                const normalized = linkedUrl.replace(/#.*$/, '');
                if (inboundMap.has(normalized)) {
                    inboundMap.set(normalized, inboundMap.get(normalized) + 1);
                }
            }
        }

        for (const page of pages.slice(1)) {
            expect(inboundMap.get(page.url.replace(/#.*$/, '')) ?? 0).toBeGreaterThan(0);
        }
    });

