    const firstLine = (snapshot: string) => snapshot.trim().split('\n')[0];
    const hasName = (snapshot: string) => /^-\s+[^\s:"]+\s+"/.test(firstLine(snapshot));
    // An unlabelled file input is named by its button text ("Choose File",
